#!/usr/bin/env python3
"""Build the executable DreamBench-SWE pilot environment."""

from __future__ import annotations

import json
import shutil
import subprocess
import textwrap
from pathlib import Path


ROOT = Path(__file__).resolve().parent
REPOS = ROOT / "repos"
TASKS_PATH = ROOT / "tasks.jsonl"
PYTEST_CMD = ["python3", "-m", "pytest", "-q"]
ORACLE_CMD = "python3 -m pytest -q"


def clean_text(text: str) -> str:
    return textwrap.dedent(text).lstrip()


def write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(clean_text(text), encoding="utf-8")


def run(cmd: list[str], cwd: Path, *, input_text: str | None = None, check: bool = True) -> subprocess.CompletedProcess[str]:
    proc = subprocess.run(
        cmd,
        cwd=str(cwd),
        input=input_text,
        text=True,
        capture_output=True,
    )
    if check and proc.returncode != 0:
        raise RuntimeError(
            f"command failed in {cwd}: {' '.join(cmd)}\n"
            f"exit={proc.returncode}\nstdout:\n{proc.stdout}\nstderr:\n{proc.stderr}"
        )
    return proc


def git(repo: Path, *args: str, check: bool = True) -> subprocess.CompletedProcess[str]:
    return run(["git", *args], repo, check=check)


def commit(repo: Path, message: str) -> None:
    git(repo, "add", "-A")
    run(
        [
            "git",
            "-c",
            "user.name=DreamBench Builder",
            "-c",
            "user.email=dreambench@example.invalid",
            "commit",
            "-m",
            message,
        ],
        repo,
    )


def tag(repo: Path, name: str) -> None:
    git(repo, "tag", "-f", name)


def seed_common(repo: Path) -> None:
    write(
        repo / ".gitignore",
        """
        __pycache__/
        .pytest_cache/
        *.pyc
        """,
    )


def expr_operator_lines(operators: list[tuple[str, str, int, str, str]]) -> list[str]:
    return [
        f"{symbol} {name} precedence={precedence} associativity={assoc}"
        for symbol, name, precedence, assoc, _expr in sorted(operators, key=lambda item: item[0])
    ]


def expr_operators_code(operators: list[tuple[str, str, int, str, str]]) -> str:
    function_blocks = []
    entries = []
    for symbol, name, precedence, assoc, expr in operators:
        func_name = f"_{name}"
        function_blocks.append(
            f"def {func_name}(left, right):\n"
            f"    return {expr}\n"
        )
        entries.append(
            f'    "{symbol}": {{"name": "{name}", "precedence": {precedence}, '
            f'"associativity": "{assoc}", "function": {func_name}}},'
        )
    return "\n".join(function_blocks) + "\n\nOPERATORS = {\n" + "\n".join(entries) + "\n}\n\n" + clean_text(
        r'''
        def operator_symbols():
            return sorted(OPERATORS, key=len, reverse=True)


        def operator_help_lines():
            return tuple(
                f"{symbol} {meta['name']} precedence={meta['precedence']} associativity={meta['associativity']}"
                for symbol, meta in sorted(OPERATORS.items())
            )
        '''
    )


def expr_help_code(operators: list[tuple[str, str, int, str, str]]) -> str:
    lines = expr_operator_lines(operators)
    body = "\n".join(f'    "{line}",' for line in lines)
    return "# Generated by tools/generate_operator_help.py.\nHELP_LINES = (\n" + body + "\n)\n"


EXPR_OPERATORS_BASE = [
    ("+", "add", 10, "left", "left + right"),
    ("-", "subtract", 10, "left", "left - right"),
    ("*", "multiply", 20, "left", "left * right"),
]


def expr_evaluator_code(features: set[str]) -> str:
    if "vars" in features or "compile" in features:
        core = r'''
        from .operator_help import HELP_LINES
        from .operators import OPERATORS, operator_symbols


        class ExpressionError(ValueError):
            pass


        def _error(code, message):
            return ExpressionError(f"EXPR_{code}: {message}")


        def tokenize(text):
            tokens = []
            index = 0
            symbols = operator_symbols()
            while index < len(text):
                char = text[index]
                if char.isspace():
                    index += 1
                    continue
                if char.isdigit():
                    start = index
                    while index < len(text) and text[index].isdigit():
                        index += 1
                    tokens.append(int(text[start:index]))
                    continue
                if char.isalpha() or char == "_":
                    start = index
                    while index < len(text) and (text[index].isalnum() or text[index] == "_"):
                        index += 1
                    tokens.append(("name", text[start:index]))
                    continue
                if char in "()":
                    tokens.append(char)
                    index += 1
                    continue
                matched = None
                for symbol in symbols:
                    if text.startswith(symbol, index):
                        matched = symbol
                        break
                if matched is None:
                    raise _error("TOKEN", f"unexpected character {char!r}")
                tokens.append(matched)
                index += len(matched)
            return tokens


        class Parser:
            def __init__(self, tokens, variables=None, allow_unbound=False):
                self.tokens = list(tokens)
                self.position = 0
                self.variables = variables or {}
                self.allow_unbound = allow_unbound

            def current(self):
                if self.position >= len(self.tokens):
                    return None
                return self.tokens[self.position]

            def consume(self):
                token = self.current()
                self.position += 1
                return token

            def parse(self):
                if not self.tokens:
                    raise _error("PARSE", "empty expression")
                value = self.parse_expression()
                if self.current() is not None:
                    raise _error("PARSE", f"unexpected token {self.current()!r}")
                return value

            def parse_expression(self, min_precedence=0):
                left = self.parse_primary()
                while self.current() in OPERATORS:
                    symbol = self.current()
                    meta = OPERATORS[symbol]
                    precedence = meta["precedence"]
                    if precedence < min_precedence:
                        break
                    self.consume()
                    next_min = precedence + 1 if meta["associativity"] == "left" else precedence
                    right = self.parse_expression(next_min)
                    try:
                        left = meta["function"](left, right)
                    except ZeroDivisionError:
                        raise _error("MATH", "division by zero")
                return left

            def parse_primary(self):
                token = self.current()
                if isinstance(token, int):
                    self.consume()
                    return token
                if isinstance(token, tuple) and token[0] == "name":
                    self.consume()
                    name = token[1]
                    if name in self.variables:
                        return self.variables[name]
                    if self.allow_unbound:
                        return 0
                    raise _error("NAME", f"unknown variable {name!r}")
                if token == "(":
                    self.consume()
                    value = self.parse_expression()
                    if self.current() != ")":
                        raise _error("PARSE", "expected ')'")
                    self.consume()
                    return value
                raise _error("PARSE", "expected number, variable, or '('")


        def evaluate(expression, variables=None):
            return Parser(tokenize(expression), variables=variables).parse()


        def list_operator_help():
            return list(HELP_LINES)
        '''
    else:
        core = r'''
        from .operator_help import HELP_LINES
        from .operators import OPERATORS, operator_symbols


        class ExpressionError(ValueError):
            pass


        def _error(code, message):
            return ExpressionError(f"EXPR_{code}: {message}")


        def tokenize(text):
            tokens = []
            index = 0
            symbols = operator_symbols()
            while index < len(text):
                char = text[index]
                if char.isspace():
                    index += 1
                    continue
                if char.isdigit():
                    start = index
                    while index < len(text) and text[index].isdigit():
                        index += 1
                    tokens.append(int(text[start:index]))
                    continue
                if char in "()":
                    tokens.append(char)
                    index += 1
                    continue
                matched = None
                for symbol in symbols:
                    if text.startswith(symbol, index):
                        matched = symbol
                        break
                if matched is None:
                    raise _error("TOKEN", f"unexpected character {char!r}")
                tokens.append(matched)
                index += len(matched)
            return tokens


        class Parser:
            def __init__(self, tokens):
                self.tokens = list(tokens)
                self.position = 0

            def current(self):
                if self.position >= len(self.tokens):
                    return None
                return self.tokens[self.position]

            def consume(self):
                token = self.current()
                self.position += 1
                return token

            def parse(self):
                if not self.tokens:
                    raise _error("PARSE", "empty expression")
                value = self.parse_expression()
                if self.current() is not None:
                    raise _error("PARSE", f"unexpected token {self.current()!r}")
                return value

            def parse_expression(self, min_precedence=0):
                left = self.parse_primary()
                while self.current() in OPERATORS:
                    symbol = self.current()
                    meta = OPERATORS[symbol]
                    precedence = meta["precedence"]
                    if precedence < min_precedence:
                        break
                    self.consume()
                    next_min = precedence + 1 if meta["associativity"] == "left" else precedence
                    right = self.parse_expression(next_min)
                    try:
                        left = meta["function"](left, right)
                    except ZeroDivisionError:
                        raise _error("MATH", "division by zero")
                return left

            def parse_primary(self):
                token = self.current()
                if isinstance(token, int):
                    self.consume()
                    return token
                if token == "(":
                    self.consume()
                    value = self.parse_expression()
                    if self.current() != ")":
                        raise _error("PARSE", "expected ')'")
                    self.consume()
                    return value
                raise _error("PARSE", "expected number or '('")


        def evaluate(expression):
            return Parser(tokenize(expression)).parse()


        def list_operator_help():
            return list(HELP_LINES)
        '''
    extras = []
    if "safe" in features:
        signature = "def safe_evaluate(expression, default=None, variables=None):" if ("vars" in features or "compile" in features) else "def safe_evaluate(expression, default=None):"
        call = "evaluate(expression, variables=variables)" if ("vars" in features or "compile" in features) else "evaluate(expression)"
        extras.append(clean_text(f"""

        {signature}
            try:
                return {call}
            except ExpressionError:
                return default
        """))
    if "many" in features:
        signature = "def evaluate_many(lines, variables=None):" if ("vars" in features or "compile" in features) else "def evaluate_many(lines):"
        call = "evaluate(line, variables=variables)" if ("vars" in features or "compile" in features) else "evaluate(line)"
        extras.append(clean_text(f"""

        {signature}
            values = []
            for line_number, line in enumerate(lines, start=1):
                line = line.strip()
                if not line:
                    continue
                try:
                    values.append({call})
                except ExpressionError as exc:
                    raise _error("BATCH", f"line {{line_number}}: {{exc}}")
            return values
        """))
    if "compile" in features:
        extras.append(
            clean_text(r'''

            def compile_expression(expression):
                tokens = tokenize(expression)
                Parser(tokens, variables={}, allow_unbound=True).parse()

                def _compiled(variables=None):
                    return Parser(tokens, variables=variables or {}).parse()

                return _compiled
            ''')
        )
    return clean_text(core) + ("\n\n" + "\n\n".join(extras) if extras else "")


def expr_init_code(features: set[str]) -> str:
    exports = ["ExpressionError", "evaluate", "list_operator_help"]
    if "safe" in features:
        exports.append("safe_evaluate")
    if "many" in features:
        exports.append("evaluate_many")
    if "compile" in features:
        exports.append("compile_expression")
    return "from .evaluator import " + ", ".join(exports) + "\n"


def seed_exprmini(repo: Path) -> None:
    seed_common(repo)
    write(
        repo / "CONVENTIONS.md",
        """
        # exprmini conventions

        - Public expression failures raise `ExpressionError` with `EXPR_<CODE>: <message>`.
        - Operator metadata in `exprmini/operators.py` is the source of truth.
        - `exprmini/operator_help.py` is generated from the operator registry and must change with it.
        """,
    )
    write(repo / "exprmini" / "operators.py", expr_operators_code(EXPR_OPERATORS_BASE))
    write(repo / "exprmini" / "operator_help.py", expr_help_code(EXPR_OPERATORS_BASE))
    write(repo / "exprmini" / "evaluator.py", expr_evaluator_code(set()))
    write(repo / "exprmini" / "__init__.py", expr_init_code(set()))
    write(
        repo / "tools" / "generate_operator_help.py",
        r'''
        from pathlib import Path

        from exprmini.operators import operator_help_lines


        def main():
            lines = ["# Generated by tools/generate_operator_help.py.", "HELP_LINES = ("]
            lines.extend(f'    "{line}",' for line in operator_help_lines())
            lines.append(")")
            Path("exprmini/operator_help.py").write_text("\n".join(lines) + "\n", encoding="utf-8")


        if __name__ == "__main__":
            main()
        ''',
    )
    write(
        repo / "tests" / "test_evaluator.py",
        r'''
        import pytest

        from exprmini import ExpressionError, evaluate, list_operator_help
        from exprmini.operator_help import HELP_LINES
        from exprmini.operators import operator_help_lines


        def test_precedence_and_parentheses():
            assert evaluate("2 + 3 * 4") == 14
            assert evaluate("(2 + 3) * 4") == 20


        def test_error_prefix():
            with pytest.raises(ExpressionError, match=r"^EXPR_PARSE:"):
                evaluate("1 +")


        def test_generated_help_matches_operator_registry():
            assert HELP_LINES == operator_help_lines()
            assert list_operator_help() == list(HELP_LINES)
        ''',
    )


def seed_configly(repo: Path) -> None:
    seed_common(repo)
    write(
        repo / "CONVENTIONS.md",
        """
        # configly conventions

        - Parser errors must include a concrete line number when input text is malformed.
        - Public keys are normalized through `normalize_key`.
        - Data containers should remain dict-compatible when architecture changes add helpers.
        """,
    )
    write(repo / "configly" / "parser.py", config_parser_code(set()))
    write(repo / "configly" / "__init__.py", config_init_code(set()))
    write(
        repo / "tests" / "test_parser.py",
        r'''
        import pytest

        from configly import ParseError, dump_ini, normalize_key, parse_csv, parse_ini


        def test_parse_ini_sections_and_keys():
            data = parse_ini("[server]\nHost-Name = localhost\nport=8080\n")
            assert data == {"server": {"host_name": "localhost", "port": "8080"}}


        def test_parse_error_has_line_number():
            with pytest.raises(ParseError, match=r"line 1:"):
                parse_ini("missing section = true\n")


        def test_dump_ini_round_trip_shape():
            text = dump_ini({"server": {"host": "localhost", "port": "8080"}})
            assert text == "[server]\nhost=localhost\nport=8080\n"


        def test_parse_csv_normalizes_headers():
            rows = parse_csv("First-Name,Age\nAda,37\n")
            assert rows == [{"first_name": "Ada", "age": "37"}]


        def test_normalize_key():
            assert normalize_key("Api-Key") == "api_key"
        ''',
    )


def config_parser_code(features: set[str]) -> str:
    has_config = "config" in features or "select" in features or "merge" in features or "many" in features
    has_select = "select" in features or "merge" in features or "many" in features
    has_merge = "merge" in features or "many" in features
    has_many = "many" in features
    has_sort = "sort" in features
    has_coerce = "coerce" in features
    has_strict = "strict_csv" in features
    has_redact = "redact" in features

    lines: list[str] = [
        "import csv",
        "import io",
        "",
        "",
        "class ParseError(ValueError):",
        "    pass",
        "",
        "",
        "def normalize_key(key):",
        "    return key.strip().lower().replace('-', '_')",
        "",
        "",
    ]
    if has_config:
        lines.extend(
            [
                "class Config(dict):",
                "    def get_path(self, path, default=None):",
                "        section, _, key = path.partition('.')",
                "        if not section or not key:",
                "            return default",
                "        return self.get(section, {}).get(normalize_key(key), default)",
                "",
                "    def as_dict(self):",
                "        return {section: dict(values) for section, values in self.items()}",
            ]
        )
        if has_select:
            lines.extend(
                [
                    "",
                    "    def select(self, section, default=None):",
                    "        if section in self:",
                    "            return dict(self[section])",
                    "        return default",
                ]
            )
        lines.append("")
        lines.append("")
    if has_coerce:
        lines.extend(
            [
                "def _coerce_value(value):",
                "    lowered = value.lower()",
                "    if lowered in {'true', 'yes', 'on'}:",
                "        return True",
                "    if lowered in {'false', 'no', 'off'}:",
                "        return False",
                "    if value.isdigit() or (value.startswith('-') and value[1:].isdigit()):",
                "        return int(value)",
                "    return value",
                "",
                "",
            ]
        )
    parse_signature = "def parse_ini(text, coerce=False):" if has_coerce else "def parse_ini(text):"
    lines.extend(
        [
            parse_signature,
            "    data = {}",
            "    current = None",
            "    for line_no, raw_line in enumerate(text.splitlines(), start=1):",
            "        line = raw_line.strip()",
            "        if not line or line.startswith('#') or line.startswith(';'):",
            "            continue",
            "        if line.startswith('[') and line.endswith(']'):",
            "            current = normalize_key(line[1:-1])",
            "            data.setdefault(current, {})",
            "            continue",
            "        if '=' not in line:",
            "            raise ParseError(f'line {line_no}: expected key=value')",
            "        if current is None:",
            "            raise ParseError(f'line {line_no}: key outside section')",
            "        key, value = line.split('=', 1)",
            "        value = value.strip()",
        ]
    )
    if has_coerce:
        lines.append("        if coerce:")
        lines.append("            value = _coerce_value(value)")
    lines.extend(
        [
            "        data[current][normalize_key(key)] = value",
            "    return Config(data)" if has_config else "    return data",
            "",
            "",
        ]
    )
    if has_sort:
        lines.extend(
            [
                "def dump_ini(config, sort_keys=False):",
                "    lines = []",
                "    sections = sorted(config) if sort_keys else list(config)",
                "    for section in sections:",
                "        values = config[section]",
                "        lines.append(f'[{section}]')",
                "        keys = sorted(values) if sort_keys else list(values)",
                "        for key in keys:",
                "            lines.append(f'{key}={values[key]}')",
                "    return '\\n'.join(lines) + ('\\n' if lines else '')",
                "",
                "",
            ]
        )
    else:
        lines.extend(
            [
                "def dump_ini(config):",
                "    lines = []",
                "    for section, values in config.items():",
                "        lines.append(f'[{section}]')",
                "        for key, value in values.items():",
                "            lines.append(f'{key}={value}')",
                "    return '\\n'.join(lines) + ('\\n' if lines else '')",
                "",
                "",
            ]
        )
    lines.extend(
        [
            "def parse_csv(text, strict=False):" if has_strict else "def parse_csv(text):",
            "    rows = list(csv.reader(io.StringIO(text)))",
            "    if not rows:",
            "        return []",
            "    headers = [normalize_key(header) for header in rows[0]]",
            "    records = []",
            "    for line_no, row in enumerate(rows[1:], start=2):",
        ]
    )
    if has_strict:
        lines.extend(
            [
                "        if strict and len(row) != len(headers):",
                "            raise ParseError(f'line {line_no}: expected {len(headers)} columns, got {len(row)}')",
            ]
        )
    lines.extend(
        [
            "        padded = row + [''] * max(0, len(headers) - len(row))",
            "        records.append({header: padded[index] for index, header in enumerate(headers)})",
            "    return records",
            "",
            "",
        ]
    )
    if has_merge:
        lines.extend(
            [
                "def merge_configs(base, override):",
                "    merged = Config(base).as_dict() if isinstance(base, Config) else {section: dict(values) for section, values in base.items()}",
                "    other = override.as_dict() if isinstance(override, Config) else {section: dict(values) for section, values in override.items()}",
                "    for section, values in other.items():",
                "        merged.setdefault(section, {}).update(values)",
                "    return Config(merged)",
                "",
                "",
            ]
        )
    if has_many:
        lines.extend(
            [
                "def parse_ini_many(named_texts):",
                "    merged = Config()",
                "    for name, text in named_texts.items():",
                "        try:",
                "            parsed = parse_ini(text)",
                "        except ParseError as exc:",
                "            raise ParseError(f'{name}: {exc}')",
                "        merged = merge_configs(merged, parsed)",
                "    return merged",
                "",
                "",
            ]
        )
    if has_redact:
        lines.extend(
            [
                "def redact(config, secrets=('password', 'token', 'secret')):",
                "    secret_keys = {normalize_key(key) for key in secrets}",
                "    output = {}",
                "    for section, values in config.items():",
                "        output[section] = {}",
                "        for key, value in values.items():",
                "            output[section][key] = '<redacted>' if normalize_key(key) in secret_keys else value",
                "    return output",
                "",
            ]
        )
    return "\n".join(lines)


def config_init_code(features: set[str]) -> str:
    names = ["ParseError", "dump_ini", "normalize_key", "parse_csv", "parse_ini"]
    if {"config", "select", "merge", "many"} & features:
        names.append("Config")
    if "merge" in features or "many" in features:
        names.append("merge_configs")
    if "many" in features:
        names.append("parse_ini_many")
    if "redact" in features:
        names.append("redact")
    return "from .parser import " + ", ".join(names) + "\n"


def todo_store_code(features: set[str]) -> str:
    metadata = "metadata" in features
    if metadata:
        return clean_text(
            r'''
            import json
            from pathlib import Path


            def _empty_db():
                return {"tasks": [], "next_id": 1}


            def load_database(path):
                path = Path(path)
                if not path.exists():
                    return _empty_db()
                data = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(data, list):
                    next_id = max((task["id"] for task in data), default=0) + 1
                    return {"tasks": data, "next_id": next_id}
                data.setdefault("tasks", [])
                data.setdefault("next_id", max((task["id"] for task in data["tasks"]), default=0) + 1)
                return data


            def save_database(path, db):
                path = Path(path)
                path.write_text(json.dumps(db, indent=2, sort_keys=True) + "\n", encoding="utf-8")


            def load_tasks(path):
                return load_database(path)["tasks"]


            def save_tasks(path, tasks):
                next_id = max((task["id"] for task in tasks), default=0) + 1
                save_database(path, {"tasks": tasks, "next_id": next_id})


            def add_task(path, title, due=None, labels=None):
                db = load_database(path)
                task = {"id": db["next_id"], "title": title, "done": False}
                if due:
                    task["due"] = due
                if labels:
                    task["labels"] = list(labels)
                db["tasks"].append(task)
                db["next_id"] += 1
                save_database(path, db)
                return task


            def update_task(path, task_id, **changes):
                db = load_database(path)
                for task in db["tasks"]:
                    if task["id"] == task_id:
                        task.update(changes)
                        save_database(path, db)
                        return task
                raise KeyError(task_id)


            def delete_task(path, task_id):
                db = load_database(path)
                for index, task in enumerate(db["tasks"]):
                    if task["id"] == task_id:
                        removed = db["tasks"].pop(index)
                        save_database(path, db)
                        return removed
                raise KeyError(task_id)


            def purge_done(path):
                db = load_database(path)
                before = len(db["tasks"])
                db["tasks"] = [task for task in db["tasks"] if not task["done"]]
                save_database(path, db)
                return before - len(db["tasks"])
            '''
        )
    return clean_text(
        r'''
        import json
        from pathlib import Path


        def load_tasks(path):
            path = Path(path)
            if not path.exists():
                return []
            return json.loads(path.read_text(encoding="utf-8"))


        def save_tasks(path, tasks):
            path = Path(path)
            path.write_text(json.dumps(tasks, indent=2, sort_keys=True) + "\n", encoding="utf-8")


        def add_task(path, title, due=None, labels=None):
            tasks = load_tasks(path)
            next_id = max((task["id"] for task in tasks), default=0) + 1
            task = {"id": next_id, "title": title, "done": False}
            if due:
                task["due"] = due
            if labels:
                task["labels"] = list(labels)
            tasks.append(task)
            save_tasks(path, tasks)
            return task


        def update_task(path, task_id, **changes):
            tasks = load_tasks(path)
            for task in tasks:
                if task["id"] == task_id:
                    task.update(changes)
                    save_tasks(path, tasks)
                    return task
            raise KeyError(task_id)


        def delete_task(path, task_id):
            tasks = load_tasks(path)
            for index, task in enumerate(tasks):
                if task["id"] == task_id:
                    removed = tasks.pop(index)
                    save_tasks(path, tasks)
                    return removed
            raise KeyError(task_id)
        '''
    )


def todo_cli_code(features: set[str]) -> str:
    has_sort = "sort" in features
    has_due = "due" in features
    has_metadata = "metadata" in features
    has_status = "status" in features
    has_rename = "rename" in features
    has_delete = "delete" in features
    has_stats = "stats" in features
    has_search = "search" in features

    lines = [
        "import sys",
        "",
        "from . import store",
        "",
        "",
        "def _emit(stdout, line):",
        "    stdout.write(line + '\\n')",
        "",
        "",
        "def _format_task(task):",
        "    status = 'done' if task.get('done') else 'open'",
        "    parts = ['TASK', str(task['id']), status, task['title']]",
        "    if task.get('due'):",
        "        parts.append(f\"due={task['due']}\")",
        "    if task.get('labels'):",
        "        parts.append('labels=' + ','.join(task['labels']))",
        "    return '|'.join(parts)",
        "",
        "",
        "def _parse_global(argv):",
        "    db_path = 'tasks.json'",
        "    argv = list(argv)",
        "    while argv and argv[0] == '--file':",
        "        argv.pop(0)",
        "        if not argv:",
        "            raise ValueError('missing --file value')",
        "        db_path = argv.pop(0)",
        "    return db_path, argv",
        "",
        "",
        "def main(argv=None, stdout=None):",
        "    argv = list(sys.argv[1:] if argv is None else argv)",
        "    stdout = sys.stdout if stdout is None else stdout",
        "    try:",
        "        db_path, argv = _parse_global(argv)",
        "    except ValueError as exc:",
        "        _emit(stdout, f'ERR|usage|{exc}')",
        "        return 2",
        "    if not argv:",
        "        _emit(stdout, 'ERR|usage|missing command')",
        "        return 2",
        "    command = argv.pop(0)",
        "",
        "    if command == 'add':",
        "        due = None",
        "        labels = []",
        "        title_parts = []",
        "        while argv:",
        "            token = argv.pop(0)",
    ]
    if has_due:
        lines.extend(
            [
                "            if token == '--due':",
                "                if not argv:",
                "                    _emit(stdout, 'ERR|usage|missing due date')",
                "                    return 2",
                "                due = argv.pop(0)",
                "                continue",
            ]
        )
    if "labels" in features:
        lines.extend(
            [
                "            if token == '--label':",
                "                if not argv:",
                "                    _emit(stdout, 'ERR|usage|missing label')",
                "                    return 2",
                "                labels.append(argv.pop(0))",
                "                continue",
            ]
        )
    lines.extend(
        [
            "            title_parts.append(token)",
            "        title = ' '.join(title_parts).strip()",
            "        if not title:",
            "            _emit(stdout, 'ERR|usage|missing title')",
            "            return 2",
            "        task = store.add_task(db_path, title, due=due, labels=labels)",
            "        _emit(stdout, f\"OK|added|{task['id']}|{task['title']}\")",
            "        return 0",
            "",
            "    if command == 'list':",
            "        sort_key = None",
            "        wanted_status = 'all'",
            "        while argv:",
            "            token = argv.pop(0)",
        ]
    )
    if has_sort:
        lines.extend(
            [
                "            if token == '--sort':",
                "                if not argv:",
                "                    _emit(stdout, 'ERR|usage|missing sort key')",
                "                    return 2",
                "                sort_key = argv.pop(0)",
                "                continue",
            ]
        )
    if has_status:
        lines.extend(
            [
                "            if token == '--status':",
                "                if not argv:",
                "                    _emit(stdout, 'ERR|usage|missing status')",
                "                    return 2",
                "                wanted_status = argv.pop(0)",
                "                continue",
            ]
        )
    lines.extend(
        [
            "        tasks = store.load_tasks(db_path)",
        ]
    )
    if has_status:
        lines.extend(
            [
                "        if wanted_status in {'open', 'done'}:",
                "            want_done = wanted_status == 'done'",
                "            tasks = [task for task in tasks if task.get('done') is want_done]",
            ]
        )
    if has_sort:
        lines.extend(
            [
                "        if sort_key == 'title':",
                "            tasks = sorted(tasks, key=lambda task: (task['title'].casefold(), task['id']))",
            ]
        )
    lines.extend(
        [
            "        for task in tasks:",
            "            _emit(stdout, _format_task(task))",
            "        return 0",
            "",
            "    if command == 'complete':",
            "        if not argv:",
            "            _emit(stdout, 'ERR|usage|missing id')",
            "            return 2",
            "        try:",
            "            task = store.update_task(db_path, int(argv[0]), done=True)",
            "        except (KeyError, ValueError):",
            "            _emit(stdout, f'ERR|not_found|{argv[0]}')",
            "            return 1",
            "        _emit(stdout, f\"OK|completed|{task['id']}|{task['title']}\")",
            "        return 0",
            "",
        ]
    )
    if has_rename:
        lines.extend(
            [
                "    if command == 'rename':",
                "        if len(argv) < 2:",
                "            _emit(stdout, 'ERR|usage|rename needs id and title')",
                "            return 2",
                "        try:",
                "            task_id = int(argv.pop(0))",
                "            task = store.update_task(db_path, task_id, title=' '.join(argv))",
                "        except (KeyError, ValueError):",
                "            _emit(stdout, 'ERR|not_found|rename target')",
                "            return 1",
                "        _emit(stdout, f\"OK|renamed|{task['id']}|{task['title']}\")",
                "        return 0",
                "",
            ]
        )
    if has_delete:
        lines.extend(
            [
                "    if command == 'delete':",
                "        if not argv:",
                "            _emit(stdout, 'ERR|usage|missing id')",
                "            return 2",
                "        try:",
                "            task = store.delete_task(db_path, int(argv[0]))",
                "        except (KeyError, ValueError):",
                "            _emit(stdout, f'ERR|not_found|{argv[0]}')",
                "            return 1",
                "        _emit(stdout, f\"OK|deleted|{task['id']}|{task['title']}\")",
                "        return 0",
                "",
            ]
        )
    if has_stats:
        lines.extend(
            [
                "    if command == 'stats':",
                "        tasks = store.load_tasks(db_path)",
                "        done = sum(1 for task in tasks if task.get('done'))",
                "        total = len(tasks)",
                "        _emit(stdout, f'STATS|open={total - done}|done={done}|total={total}')",
                "        return 0",
                "",
            ]
        )
    if has_search:
        lines.extend(
            [
                "    if command == 'search':",
                "        needle = ' '.join(argv).casefold()",
                "        for task in store.load_tasks(db_path):",
                "            if needle in task['title'].casefold():",
                "                _emit(stdout, _format_task(task))",
                "        return 0",
                "",
            ]
        )
    if has_metadata:
        lines.extend(
            [
                "    if command == 'purge-done':",
                "        count = store.purge_done(db_path)",
                "        _emit(stdout, f'OK|purged|{count}')",
                "        return 0",
                "",
            ]
        )
    lines.extend(
        [
            "    _emit(stdout, f'ERR|unknown_command|{command}')",
            "    return 2",
            "",
            "",
            "if __name__ == '__main__':",
            "    raise SystemExit(main())",
        ]
    )
    return "\n".join(lines) + "\n"


def todo_init_code() -> str:
    return "from .cli import main\n"


def seed_todolite(repo: Path) -> None:
    seed_common(repo)
    write(
        repo / "CONVENTIONS.md",
        """
        # todolite conventions

        - CLI output is machine-readable pipe records, never prose.
        - Item command success records use `OK|verb|id|title`.
        - Listed tasks use `TASK|id|status|title`, with optional `key=value` fields appended.
        """,
    )
    write(repo / "todolite" / "store.py", todo_store_code(set()))
    write(repo / "todolite" / "cli.py", todo_cli_code(set()))
    write(repo / "todolite" / "__init__.py", todo_init_code())
    write(
        repo / "tests" / "test_cli.py",
        r'''
        import io

        from todolite import main


        def run_cli(tmp_path, *args):
            out = io.StringIO()
            code = main(["--file", str(tmp_path / "tasks.json"), *args], out)
            return code, out.getvalue().splitlines()


        def test_add_list_and_complete(tmp_path):
            assert run_cli(tmp_path, "add", "Buy", "milk") == (0, ["OK|added|1|Buy milk"])
            assert run_cli(tmp_path, "list") == (0, ["TASK|1|open|Buy milk"])
            assert run_cli(tmp_path, "complete", "1") == (0, ["OK|completed|1|Buy milk"])
            assert run_cli(tmp_path, "list") == (0, ["TASK|1|done|Buy milk"])


        def test_unknown_command_is_machine_readable(tmp_path):
            code, lines = run_cli(tmp_path, "wat")
            assert code == 2
            assert lines == ["ERR|unknown_command|wat"]
        ''',
    )


def event(kind: str, payload: dict | None = None) -> dict:
    return {"kind": kind, "payload": payload or {}}


def task_record(
    *,
    seq_id: str,
    seq_type: str,
    session_index: int,
    repo_name: str,
    base_ref: str,
    instruction: str,
    injected_memory_event: dict,
    reference_patch: str,
    error_taxonomy_hint: str,
) -> dict:
    return {
        "seq_id": seq_id,
        "seq_type": seq_type,
        "session_index": session_index,
        "repo": repo_name,
        "base_ref": base_ref,
        "instruction": instruction,
        "injected_memory_event": injected_memory_event,
        "oracle_cmd": ORACLE_CMD,
        "expected_pass": True,
        "reference_patch": reference_patch,
        "error_taxonomy_hint": error_taxonomy_hint,
    }


def add_task(
    tasks: list[dict],
    repo: Path,
    repo_name: str,
    seq_id: str,
    seq_type: str,
    session_index: int,
    instruction: str,
    memory_event: dict,
    error_hint: str,
    base_change,
    fix_change,
) -> None:
    base_change(repo)
    commit(repo, f"{seq_id} session {session_index} failing oracle")
    base_ref = f"tasks/{seq_id}/s{session_index:02d}/base"
    tag(repo, base_ref)
    base_result = run(PYTEST_CMD, repo, check=False)
    if base_result.returncode == 0:
        raise RuntimeError(f"{repo_name} {seq_id} s{session_index} base unexpectedly passed")

    fix_change(repo)
    patch = git(repo, "diff", "--binary").stdout
    if not patch.strip():
        raise RuntimeError(f"{repo_name} {seq_id} s{session_index} produced an empty patch")
    fixed_result = run(PYTEST_CMD, repo, check=False)
    if fixed_result.returncode != 0:
        raise RuntimeError(
            f"{repo_name} {seq_id} s{session_index} fix failed\n"
            f"stdout:\n{fixed_result.stdout}\nstderr:\n{fixed_result.stderr}"
        )
    commit(repo, f"{seq_id} session {session_index} reference fix")
    tag(repo, f"tasks/{seq_id}/s{session_index:02d}/fix")
    tasks.append(
        task_record(
            seq_id=seq_id,
            seq_type=seq_type,
            session_index=session_index,
            repo_name=repo_name,
            base_ref=base_ref,
            instruction=instruction,
            injected_memory_event=memory_event,
            reference_patch=patch,
            error_taxonomy_hint=error_hint,
        )
    )


