def expr_generated_sequence(repo: Path, tasks: list[dict]) -> None:
    git(repo, "checkout", "-B", "seq/expr-generated", "seed")
    operators = list(EXPR_OPERATORS_BASE)
    seq_id = "expr-generated"
    repo_name = "exprmini"

    def fix_ops(new_ops):
        def _fix(r: Path) -> None:
            write(r / "exprmini" / "operators.py", expr_operators_code(new_ops))
            write(r / "exprmini" / "operator_help.py", expr_help_code(new_ops))

        return _fix

    additions = [
        ("**", "power", 30, "right", "left ** right", "2 ** 3 ** 2", 512),
        ("//", "floor_divide", 20, "left", "left // right", "7 // 2", 3),
        ("%", "modulo", 20, "left", "left % right", "7 % 4", 3),
        ("@", "average", 5, "left", "(left + right) // 2", "10 @ 4", 7),
    ]
    for index, (symbol, name, precedence, assoc, expr, sample, expected) in enumerate(additions, start=1):
        new_ops = operators + [(symbol, name, precedence, assoc, expr)]
        safe_symbol = name.replace("_", "-")
        add_task(
            tasks,
            repo,
            repo_name,
            seq_id,
            "generated-files",
            index,
            f"Add the {symbol} operator ({name}) to the evaluator and regenerate exprmini/operator_help.py from the operator registry.",
            event("none" if index == 1 else "human_feedback", {"learned": "Operator help is generated; update it with operator registry changes."} if index > 1 else {}),
            "generated_file_not_updated",
            lambda r, symbol=symbol, name=name, sample=sample, expected=expected: write(
                r / "tests" / f"test_operator_{safe_symbol}.py",
                f'''
                from exprmini import evaluate
                from exprmini.operator_help import HELP_LINES
                from exprmini.operators import operator_help_lines


                def test_operator_{name}_evaluates():
                    assert evaluate("{sample}") == {expected}


                def test_operator_{name}_help_is_regenerated():
                    assert HELP_LINES == operator_help_lines()
                    assert any(line.startswith("{symbol} {name} ") for line in HELP_LINES)
                ''',
            ),
            fix_ops(new_ops),
        )
        operators = new_ops


