def write_loader() -> None:
    write(
        ROOT / "load_env.py",
        r'''
        #!/usr/bin/env python3
        """Loader and oracle runner for the executable DreamBench-SWE pilot tasks."""

        from __future__ import annotations

        import json
        import shutil
        import subprocess
        import sys
        import tempfile
        from pathlib import Path


        ENV_ROOT = Path(__file__).resolve().parent
        REPOS_ROOT = ENV_ROOT / "repos"
        TASKS_PATH = ENV_ROOT / "tasks.jsonl"


        def load_tasks(tasks_path: Path | str = TASKS_PATH) -> list[dict]:
            path = Path(tasks_path)
            tasks = []
            for line in path.read_text(encoding="utf-8").splitlines():
                if line.strip():
                    tasks.append(json.loads(line))
            return tasks


        def _repo_path(repo: str | Path) -> Path:
            path = Path(repo)
            if path.exists():
                return path.resolve()
            candidate = REPOS_ROOT / str(repo)
            if candidate.exists():
                return candidate.resolve()
            raise FileNotFoundError(f"unknown repo {repo!r}")


        def _git(cwd: Path, *args: str, input_text: str | None = None) -> subprocess.CompletedProcess[str]:
            return subprocess.run(
                ["git", *args],
                cwd=str(cwd),
                input=input_text,
                text=True,
                capture_output=True,
            )


        def materialize(repo: str | Path, base_ref: str, dest: str | Path | None = None) -> Path:
            repo_dir = _repo_path(repo)
            if dest is None:
                dest_path = Path(tempfile.mkdtemp(prefix=f"dreambench-{repo_dir.name}-"))
            else:
                dest_path = Path(dest)
                dest_path.mkdir(parents=True, exist_ok=True)
            clone = subprocess.run(
                ["git", "clone", "--quiet", "--no-hardlinks", str(repo_dir), str(dest_path)],
                text=True,
                capture_output=True,
            )
            if clone.returncode != 0:
                raise RuntimeError(f"git clone failed: {clone.stderr}")
            resolved = _git(dest_path, "rev-parse", "--verify", f"{base_ref}^{{commit}}")
            if resolved.returncode != 0:
                resolved = _git(dest_path, "rev-parse", "--verify", f"origin/{base_ref}^{{commit}}")
            if resolved.returncode != 0:
                raise RuntimeError(f"could not resolve base_ref {base_ref!r}: {resolved.stderr}")
            commit = resolved.stdout.strip()
            checkout = _git(dest_path, "checkout", "--quiet", "--detach", commit)
            if checkout.returncode != 0:
                raise RuntimeError(f"git checkout failed: {checkout.stderr}")
            return dest_path


        def apply_patch(worktree: str | Path, patch_text: str) -> dict:
            path = Path(worktree)
            proc = _git(path, "apply", "--whitespace=nowarn", input_text=patch_text)
            return {
                "passed": proc.returncode == 0,
                "stdout": proc.stdout,
                "stderr": proc.stderr,
                "exit_code": proc.returncode,
            }


        def run_oracle(worktree: str | Path, oracle_cmd: str) -> dict:
            proc = subprocess.run(
                oracle_cmd,
                cwd=str(worktree),
                shell=True,
                text=True,
                capture_output=True,
            )
            return {
                "passed": proc.returncode == 0,
                "stdout": proc.stdout,
                "stderr": proc.stderr,
                "exit_code": proc.returncode,
            }


        def validate_task(task: dict) -> tuple[bool, str]:
            base_dir = materialize(task["repo"], task["base_ref"])
            try:
                base_result = run_oracle(base_dir, task["oracle_cmd"])
                if base_result["passed"]:
                    return False, "base oracle unexpectedly passed"
            finally:
                shutil.rmtree(base_dir, ignore_errors=True)

            patched_dir = materialize(task["repo"], task["base_ref"])
            try:
                patch_result = apply_patch(patched_dir, task["reference_patch"])
                if not patch_result["passed"]:
                    return False, "reference patch failed to apply: " + patch_result["stderr"]
                patched_result = run_oracle(patched_dir, task["oracle_cmd"])
                if not patched_result["passed"]:
                    return False, (
                        "patched oracle failed\nstdout:\n"
                        + patched_result["stdout"]
                        + "\nstderr:\n"
                        + patched_result["stderr"]
                    )
            finally:
                shutil.rmtree(patched_dir, ignore_errors=True)
            return True, "ok"


        def main() -> int:
            tasks = load_tasks()
            failures = []
            for index, task in enumerate(tasks, start=1):
                ok, message = validate_task(task)
                label = f"{task['seq_id']}[s{task['session_index']:02d}] {task['repo']}"
                if ok:
                    print(f"ok {index:02d} {label}")
                else:
                    print(f"FAIL {index:02d} {label}: {message}")
                    failures.append((task, message))
            print(f"validated {len(tasks) - len(failures)}/{len(tasks)} tasks")
            if failures:
                return 1
            return 0


        if __name__ == "__main__":
            raise SystemExit(main())
        ''',
    )


def write_readme() -> None:
    write(
        ROOT / "README.md",
        """
        # DreamBench-SWE Executable Pilot Environment

        This directory contains a runnable pilot task environment for DreamBench-SWE. It replaces synthetic task descriptions with small real Python repositories, git refs, pytest oracles, and known-good reference patches.

        ## Layout

        - `repos/exprmini` - tiny arithmetic-expression evaluator.
        - `repos/configly` - small INI/CSV parser.
        - `repos/todolite` - tiny task CLI.
        - `tasks.jsonl` - one task per line. Each task has a sequence id/type, session index, repo, git `base_ref`, natural-language instruction, injected memory event, oracle command, expected outcome, reference patch, and taxonomy hint.
        - `load_env.py` - stdlib loader API and self-check runner.
        - `build_env.py` - deterministic fixture generator.

        Each repo is a standalone git repository with a passing `seed` tag, source files, pytest tests, and `CONVENTIONS.md`. Task refs are lightweight git tags such as `tasks/expr-convention/s01/base`. The base refs intentionally fail their pytest oracle. Applying the task's `reference_patch` makes the oracle pass.

        ## Validate

        From the project root:

        ```bash
        python3 experiments/env/load_env.py
        ```

        The self-check clones every `(repo, base_ref)` into a fresh temp directory, confirms `pytest -q` fails, applies `reference_patch`, and confirms `pytest -q` passes.

        ## Loader API

        ```python
        from experiments.env.load_env import apply_patch, materialize, run_oracle

        worktree = materialize("exprmini", "tasks/expr-convention/s01/base")
        patch_result = apply_patch(worktree, task["reference_patch"])
        oracle_result = run_oracle(worktree, "pytest -q")
        ```

        All APIs use only the Python standard library and the local `git`/`pytest` executables. No network access is required.

        ## Task Types

        The pilot covers five DreamBench-SWE memory stressors:

        - `convention-learning` - later sessions rely on project conventions documented in `CONVENTIONS.md`.
        - `generated-files` - source changes require generated artifact updates.
        - `stale-architecture` - injected memory conflicts with the current architecture.
        - `reviewer-preference` - human feedback must be applied without overgeneralizing.
        - `flaky-test` - the correct fix is deterministic behavior, not retries or xfail markers.

        ## Scaling To SWE-bench

        The same schema scales to a SWE-bench subset by replacing `repos/<name>` with pinned real project checkouts and replacing lightweight task tags with issue-specific base commits. `reference_patch` can be stored inline for tiny pilots or moved to patch files addressed by hash for larger corpora. The loader contract stays the same: materialize a base ref, run the oracle, apply an agent/reference patch, and rerun the oracle.

        For larger repos, add per-task setup metadata only when necessary, keep oracle commands deterministic, and preserve oracle separation: wake agents should see the instruction and base checkout, not `reference_patch`, `expected_pass`, or taxonomy labels.
        """,
    )


def build() -> None:
    if REPOS.exists():
        shutil.rmtree(REPOS)
    REPOS.mkdir(parents=True)
    if TASKS_PATH.exists():
        TASKS_PATH.unlink()

    tasks: list[dict] = []
    seeds = {
        "exprmini": seed_exprmini,
        "configly": seed_configly,
        "todolite": seed_todolite,
    }
    for name, seed_func in seeds.items():
        repo = REPOS / name
        repo.mkdir(parents=True)
        run(["git", "init", "-b", "main"], repo)
        seed_func(repo)
        commit(repo, "seed passing project")
        tag(repo, "seed")
        seed_result = run(PYTEST_CMD, repo, check=False)
        if seed_result.returncode != 0:
            raise RuntimeError(f"{name} seed tests failed\n{seed_result.stdout}\n{seed_result.stderr}")

    expr_repo = REPOS / "exprmini"
    expr_convention_sequence(expr_repo, tasks)
    expr_generated_sequence(expr_repo, tasks)

    config_repo = REPOS / "configly"
    config_stale_sequence(config_repo, tasks)
    config_reviewer_sequence(config_repo, tasks)

    todo_repo = REPOS / "todolite"
    todo_flaky_sequence(todo_repo, tasks)
    todo_convention_sequence(todo_repo, tasks)

    TASKS_PATH.write_text(
        "".join(json.dumps(task, sort_keys=True) + "\n" for task in tasks),
        encoding="utf-8",
    )
    write_loader()
    write_readme()


if __name__ == "__main__":
    build()
